func (e *Event) Write(data interface{}) {
	e.Lock()
	defer e.Unlock()

	tmp := []callback{}
	for _, cb := range e.Callbacks {
		go cb.f(data)
		if !cb.once {
			tmp = append(tmp, cb)
		}
	}
	e.Callbacks = tmp
}
